import React, { useState } from 'react';
import api from '../api';

function LoginPage({ onLogin }) {

    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    async function handleSubmit(e) {

        e.preventDefault();
        setError('');
        setLoading(true);

        try {

            var response = await api.login({ username, password });
            onLogin(response.data);

        } catch (err) {

            var message = err.response?.data?.message || 'Login failed. Please try again.';
            setError(message);

        } finally {

            setLoading(false);

        }

    }

    return (

        <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #1a1a2e 0%, #141428 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '1rem' }}>

            <div style={{ width: '100%', maxWidth: '380px', background: '#fff', borderRadius: '16px', padding: '2.5rem', boxShadow: '0 20px 60px rgba(0,0,0,0.3)' }}>

                <div style={{ textAlign: 'center', marginBottom: '2rem' }}>

                    <h1 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 700, color: '#1a1a2e' }}>
                        CAR<span style={{ color: '#fbbf24' }}>RENTAL</span>
                    </h1>

                    <p style={{ margin: '0.3rem 0 0', color: '#6b7280', fontSize: '0.85rem' }}>
                        Sign in to your account
                    </p>

                </div>

                {error && (

                    <div style={{ background: '#fef2f2', color: '#dc2626', padding: '0.7rem 1rem', borderRadius: '8px', marginBottom: '1.2rem', fontSize: '0.85rem', border: '1px solid #fecaca' }}>
                        {error}
                    </div>

                )}

                <form onSubmit={handleSubmit}>

                    <div style={{ marginBottom: '1rem' }}>

                        <label style={{ display: 'block', marginBottom: '0.3rem', fontSize: '0.85rem', fontWeight: 600, color: '#374151' }}>
                            Username
                        </label>

                        <input type="text"
                            value={username}
                            onChange={function(e) { setUsername(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.65rem 0.9rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                    <div style={{ marginBottom: '1.5rem' }}>

                        <label style={{ display: 'block', marginBottom: '0.3rem', fontSize: '0.85rem', fontWeight: 600, color: '#374151' }}>
                            Password
                        </label>

                        <input type="password"
                            value={password}
                            onChange={function(e) { setPassword(e.target.value); }}
                            required
                            style={{ width: '100%', padding: '0.65rem 0.9rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', outline: 'none', boxSizing: 'border-box' }} />

                    </div>

                    <button type="submit"
                        disabled={loading}
                        style={{ width: '100%', padding: '0.7rem', background: loading ? '#d1d5db' : '#fbbf24', color: '#1a1a2e', border: 'none', borderRadius: '8px', fontSize: '0.95rem', fontWeight: 700, cursor: loading ? 'not-allowed' : 'pointer' }}>

                        {loading ? 'Signing in...' : 'Sign In'}

                    </button>

                </form>

            </div>

        </div>

    );

}

export default LoginPage;
